import assert from 'node:assert/strict';
import { createTransport } from 'nodemailer';

if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Rallly's SMTP transport (packages/emails/src/transport.ts), as its environment configures it
const hasAuth = Boolean(process.env.SMTP_USER && process.env.SMTP_PWD);
const transport = createTransport({
  host: process.env.SMTP_HOST,
  port: process.env.SMTP_PORT ? Number.parseInt(process.env.SMTP_PORT, 10) : undefined,
  secure: process.env.SMTP_SECURE === 'true',
  auth: hasAuth ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PWD } : undefined,
  tls: { rejectUnauthorized: process.env.SMTP_REJECT_UNAUTHORIZED !== 'false', servername: process.env.SMTP_TLS_SERVERNAME },
});
assert.equal(await transport.verify(), true);
// a finalized poll's invitation, as Rallly's dispatch sends it: html and text, a reply-to, the unsubscribe header and the event
const info = await transport.sendMail({
  from: 'Rallly <noreply@rallly.world.test>',
  to: ['ada@world.test', 'bo@world.test'],
  replyTo: 'organizer@world.test',
  subject: 'Finalized: Team offsite',
  html: '<p>The date for <strong>Team offsite</strong> is set: Thursday 12 March, 10:00.</p>',
  text: 'The date for Team offsite is set: Thursday 12 March, 10:00.',
  headers: { 'List-Unsubscribe': '<https://rallly.world.test/unsubscribe>', 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
  icalEvent: { method: 'REQUEST', filename: 'invite.ics', content: 'BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Rallly//EN\r\nMETHOD:REQUEST\r\nBEGIN:VEVENT\r\nUID:team-offsite@rallly.world.test\r\nDTSTAMP:20260301T090000Z\r\nDTSTART:20260312T100000Z\r\nDTEND:20260312T110000Z\r\nSUMMARY:Team offsite\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n' },
});
assert.deepEqual([...info.accepted].sort(), ['ada@world.test', 'bo@world.test']);
assert.deepEqual(info.rejected, []);
assert.match(info.response, /^250 /);
assert.ok(info.messageId, 'the send answered no message id');
transport.close();
console.log(JSON.stringify({ accepted: info.accepted, response: info.response, messageId: info.messageId }));
